import React, { useContext, useState, useEffect } from 'react';
import { AuthContext } from '../../context/AuthContext';
import { FiPlus, FiBriefcase, FiUsers, FiArrowRight, FiCheck, FiX } from 'react-icons/fi';
import CreateProject from '../projects/CreateProject';
import API from '../../utils/api';

const ClientDashboard = () => {
  const { user } = useContext(AuthContext);
  const [showCreateProject, setShowCreateProject] = useState(false);
  const [myProjects, setMyProjects] = useState([]);
  const [selectedProject, setSelectedProject] = useState(null);
  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [appsLoading, setAppsLoading] = useState(false);

  useEffect(() => {
    fetchMyProjects();
  }, []);

  const fetchMyProjects = async () => {
    try {
      const res = await API.get('/application/client-projects');
      setMyProjects(res.data);
      setLoading(false);
    } catch (err) {
      console.error('Fetch projects error:', err);
      setLoading(false);
    }
  };

  const fetchApplications = async (projectId) => {
    setAppsLoading(true);
    setSelectedProject(projectId);
    try {
      const res = await API.get(`/application/project/${projectId}`);
      setApplications(res.data);
      setAppsLoading(false);
    } catch (err) {
      console.error('Fetch applications error:', err);
      setAppsLoading(false);
    }
  };

  const handleStatusUpdate = async (appId, status) => {
    try {
      await API.put(`/application/${appId}/status`, { status });
      // Refresh applications list
      fetchApplications(selectedProject);
    } catch (err) {
      console.error('Update status error:', err);
      alert('Failed to update status');
    }
  };

  // If showing create project form
  if (showCreateProject) {
    return (
      <div>
        <div className="max-w-7xl mx-auto px-4 py-4">
          <button
            onClick={() => setShowCreateProject(false)}
            className="text-primary hover:underline font-medium"
          >
            ← Back to Dashboard
          </button>
        </div>
        <CreateProject />
      </div>
    );
  }

  // Total application count across all projects
  const totalApplications = myProjects.reduce((sum, p) => sum + (p.applicationCount || 0), 0);

  return (
    <div className="min-h-screen bg-gray-50 py-12">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Header */}
        <div className="flex justify-between items-start mb-8">
          <div>
            <h1 className="text-4xl font-bold text-gray-800">Welcome, {user?.name}! 👋</h1>
            <p className="text-gray-600 mt-2">Manage your projects and find talented students</p>
          </div>
          <button
            onClick={() => setShowCreateProject(true)}
            className="flex items-center space-x-2 px-6 py-3 bg-primary text-white rounded-lg hover:bg-secondary transition font-semibold shadow-md"
          >
            <FiPlus />
            <span>Post New Project</span>
          </button>
        </div>

        {/* Stats */}
        <div className="grid md:grid-cols-3 gap-6 mb-8">
          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-500 text-sm">My Projects</p>
                <p className="text-3xl font-bold text-gray-800 mt-1">{myProjects.length}</p>
              </div>
              <div className="w-12 h-12 bg-primary bg-opacity-10 rounded-full flex items-center justify-center">
                <FiBriefcase className="text-primary text-2xl" />
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-500 text-sm">Total Applications</p>
                <p className="text-3xl font-bold text-gray-800 mt-1">{totalApplications}</p>
              </div>
              <div className="w-12 h-12 bg-blue-100 rounded-full flex items-center justify-center">
                <FiUsers className="text-blue-500 text-2xl" />
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-500 text-sm">Open Projects</p>
                <p className="text-3xl font-bold text-gray-800 mt-1">
                  {myProjects.filter(p => p.status === 'open').length}
                </p>
              </div>
              <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center">
                <FiCheck className="text-green-500 text-2xl" />
              </div>
            </div>
          </div>
        </div>

        <div className="grid md:grid-cols-2 gap-8">

          {/* My Projects List */}
          <div className="bg-white rounded-lg shadow-md p-6">
            <h2 className="text-2xl font-bold text-gray-800 mb-6">My Projects</h2>

            {loading ? (
              <div className="flex justify-center py-8">
                <div className="animate-spin rounded-full h-8 w-8 border-t-4 border-primary"></div>
              </div>
            ) : myProjects.length === 0 ? (
              <div className="text-center py-10">
                <p className="text-gray-500">No projects posted yet.</p>
                <button
                  onClick={() => setShowCreateProject(true)}
                  className="mt-3 px-6 py-2 bg-primary text-white rounded-lg hover:bg-secondary transition font-semibold"
                >
                  Post Your First Project
                </button>
              </div>
            ) : (
              <div className="space-y-4">
                {myProjects.map((project) => (
                  <div
                    key={project._id}
                    onClick={() => fetchApplications(project._id)}
                    className={`border rounded-lg p-4 cursor-pointer transition hover:shadow-md ${
                      selectedProject === project._id
                        ? 'border-primary bg-green-50 shadow-md'
                        : 'border-gray-200 hover:border-primary'
                    }`}
                  >
                    <div className="flex justify-between items-start">
                      <div>
                        <h3 className="font-bold text-gray-800">{project.title}</h3>
                        <p className="text-sm text-gray-600 mt-1">{project.description}</p>
                        <div className="flex flex-wrap gap-2 mt-2">
                          {project.requiredSkills.map((skill, i) => (
                            <span key={i} className="px-2 py-1 bg-white border border-gray-200 rounded-full text-xs text-gray-700">
                              {skill}
                            </span>
                          ))}
                        </div>
                        <p className="text-xs text-gray-500 mt-2">Budget: ${project.budget} | {project.duration}</p>
                      </div>
                      <div className="text-right ml-4">
                        <span className={`px-2 py-1 rounded-full text-xs font-semibold ${
                          project.status === 'open' ? 'bg-green-100 text-green-700' :
                          project.status === 'in-progress' ? 'bg-blue-100 text-blue-700' :
                          'bg-gray-100 text-gray-600'
                        }`}>
                          {project.status}
                        </span>
                        <div className="flex items-center justify-end mt-2 text-gray-500 text-sm">
                          <FiUsers className="mr-1" />
                          {project.applicationCount || 0}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Applications for Selected Project */}
          <div className="bg-white rounded-lg shadow-md p-6">
            <h2 className="text-2xl font-bold text-gray-800 mb-6">
              {selectedProject ? 'Applications' : 'Select a Project'}
            </h2>

            {!selectedProject ? (
              <div className="text-center py-10">
                <p className="text-gray-500">Click on a project to view applications</p>
                <FiArrowRight className="text-gray-300 text-4xl mx-auto mt-4" />
              </div>
            ) : appsLoading ? (
              <div className="flex justify-center py-8">
                <div className="animate-spin rounded-full h-8 w-8 border-t-4 border-primary"></div>
              </div>
            ) : applications.length === 0 ? (
              <div className="text-center py-10">
                <p className="text-gray-500">No applications received yet.</p>
              </div>
            ) : (
              <div className="space-y-4">
                {applications.map((app) => (
                  <div key={app._id} className="border border-gray-200 rounded-lg p-4">
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <div className="flex items-center gap-3">
                          <h3 className="font-bold text-gray-800">{app.student?.name}</h3>
                          {app.matchScore !== undefined && (
                            <span className={`px-2 py-1 rounded-full text-xs font-semibold ${
                              app.matchScore >= 70 ? 'bg-green-100 text-green-700' :
                              app.matchScore >= 40 ? 'bg-yellow-100 text-yellow-700' :
                              'bg-red-100 text-red-700'
                            }`}>
                              {app.matchScore}% Match
                            </span>
                          )}
                        </div>
                        <p className="text-sm text-gray-600 mt-1">{app.coverLetter}</p>
                        <p className="text-xs text-gray-500 mt-1">Proposed: ${app.proposedBudget}</p>
                      </div>

                      {/* Status + Actions */}
                      <div className="ml-4">
                        {app.status === 'pending' ? (
                          <div className="flex gap-2">
                            <button
                              onClick={() => handleStatusUpdate(app._id, 'accepted')}
                              className="p-2 bg-green-100 text-green-600 rounded-lg hover:bg-green-200 transition"
                              title="Accept"
                            >
                              <FiCheck />
                            </button>
                            <button
                              onClick={() => handleStatusUpdate(app._id, 'rejected')}
                              className="p-2 bg-red-100 text-red-600 rounded-lg hover:bg-red-200 transition"
                              title="Reject"
                            >
                              <FiX />
                            </button>
                          </div>
                        ) : (
                          <span className={`px-3 py-1 rounded-full text-xs font-semibold ${
                            app.status === 'accepted' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                          }`}>
                            {app.status.charAt(0).toUpperCase() + app.status.slice(1)}
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ClientDashboard;
